layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){ float u = uTime - aT, L = aK < .5 ? 1.250 : aK < 1.5 ? 0.600 : aK < 2.5 ? 0.900 : 0.900;
      if (u < 0. || u > L){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < 1.5){ float S = 4.400; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(vP.x, .03, -vP.y), 1.); return; }
      vec3 f = cameraPosition - aO; f.y = 0.; f = normalize(f); vec3 rt = vec3(f.z, 0., -f.x);
      if (aK < 2.5){ vP = vec2(position.x*.6, (position.y*.5 + .5)*2.2);            /* Heal: upright over the ally */
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + f*.25 + rt*vP.x + vec3(0., vP.y, 0.), 1.); return; }
      vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.3, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.35;   /* Sleep resolve: on the chest (over the head is the CC status cue's place) */
      mv.xy += position.xy*.38; vP = position.xy; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform float uTime; uniform vec3 uB, uG, uV, uW; varying vec2 vP; varying float vU, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); } float star(vec2 q, float sz){ float r = length(q), a = atan(q.y, q.x); return pow(abs(cos(a*2.)), 12.)*exp(-r/sz*1.4) + exp(-r*r/(sz*sz*.08)); } float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    float line(float d, float w){ return exp(-d*d/(w*w)); }
    void main(){ vec3 o = vec3(0.);
      if (vK < .5){
        /* telegraph (icon): thin blue circle drawn on the ground, gold arc on one side and violet on the other, a soft 4-point star
           in the centre, and an inner ring that closes in towards the centre over the fixed delay (reads as "about to resolve") */
        float r = length(vP), a = atan(vP.y, vP.x), R = 4.000;
        float fin = eox(clamp(vU/.3, 0., 1.)), draw = smoothstep(fin*6.3 - .1, fin*6.3, mod(a + 1.5708, 6.2832));
        float side = smoothstep(-.35, .35, cos(a));                                     /* +x gold (Heal), -x violet (Sleep) */
        vec3 rc = mix(uV, uG, side);
        float ring = line(r - R, .03)*(1. - draw), glow = exp(-pow((r - R)/.2, 2.))*.12*(1. - draw);
        float k = clamp(vU/1.200, 0., 1.), Ri = R*(1. - k*k)*.95;
        float inner = line(r - Ri, .02)*.55*smoothstep(0., .1, vU)*(1. - smoothstep(.95, 1., k));
        float st = (pow(abs(cos(a*2.)), 22.)*exp(-r*1.1) + exp(-r*r*6.)*.5)*.6*fin*(.8 + .2*sin(uTime*4.));
        float wash = smoothstep(R, R - .3, r)*.03;
        o = rc*(ring*.8 + glow + wash) + uB*(inner + st*.8) + uW*(line(r - R, .01)*.25*(1. - draw) + st*.3);
        o *= smoothstep(R + .4, R + .2, r);
      } else if (vK < 1.5){
        /* the single resolve: a soft pulse runs from the centre to the edge, the circle flashes and everything is gone - no zone */
        float r = length(vP), a = atan(vP.y, vP.x), R = 4.000, t = clamp(vU/.6, 0., 1.);
        float side = smoothstep(-.35, .35, cos(a)); vec3 rc = mix(uV, uG, side);
        float pr = R*eox(clamp(vU/.3, 0., 1.)), f = pow(1. - t, 1.6);
        float wave = line(r - pr, .12)*f*smoothstep(0., .5, r), edge = line(r - R, .04)*(vU < .033 ? 2. : 1.)*f;
        float core = exp(-r*r*2.)*(vU < .1 ? 1. - vU/.1 : 0.);
        o = rc*(wave*.5 + edge*.8) + uB*(core + wave*.35) + uW*edge*.3;
        o *= smoothstep(R + .4, R + .2, r);
      } else if (vK < 2.5){
        /* Heal on an eligible ally (gold): a few soft stars rise from the feet and a warm light swells on the chest, ease-out */
        float x = vP.x, y = vP.y, t = vU/.9, f = 1. - smoothstep(.5, 1., t), lum = 0., hot = 0.;
        for (int i=0;i<6;i++){ float fi = float(i), tt = clamp((vU - h1(fi)*.2)/.7, 0., 1.), e = 1. - pow(1. - tt, 3.);
          vec2 q = vec2(x - (h1(fi + 3.) - .5)*.8, y - (.1 + 1.8*e)); float l = sin(3.14159*tt);
          lum += star(q, .05)*l; hot += exp(-dot(q, q)*2500.)*l; }
        vec2 c = vec2(x, y - 1.25); lum += exp(-dot(c, c)*6.)*.35*sin(3.14159*min(t*1.4, 1.));
        o = (uG*lum + uW*hot*.8)*f*smoothstep(.6, .45, abs(x))*smoothstep(2.2, 2., y);
      } else {
        /* Sleep on an enemy (violet): the icon's crescent appears on the chest, rocks gently and sinks a little as it fades;
           no damage cue. The lasting Sleep state is the shared status cue. */
        float t = vU/.9, f = smoothstep(0., .12, vU)*(1. - smoothstep(.6, 1., t));
        vec2 q = vP - vec2(0., -.25*t); float rk = .25*sin(vU*5.); q = mat2(cos(rk), -sin(rk), sin(rk), cos(rk))*q;
        float cr = max(length(q) - .42, -(length(q - vec2(.2, .08)) - .36));
        float edge = line(cr, .03), fill = smoothstep(.02, -.04, cr)*.25;
        float st = star(q - vec2(.2, .02), .09)*.7;
        o = (uV*(edge + fill) + uW*(edge*.3 + st))*f*smoothstep(1., .85, length(vP));
      }
      o = max(o, 0.); if (!(max(o.r, max(o.g, o.b)) >= .002)) discard; gl_FragColor = vec4(o, 1.); }
